#include <functional>
int calls;
bool update(int &x, const int &y) { ++calls; x += y; return x != 0; }
int main() {
  auto f = std::not_fn(&update);
  int x = -3, y = 3;
  if (!f(x,y) || x != 0 || calls != 1) return 1;
  if (f(x,y) || x != 3 || calls != 2) return 2;
  return 0;
}

